}


            Python

    # Class representing a Stack
class Stack:

    def __init__(self):
        self.arr = [0]*5
        self.top = -1

    # Method to push element
    def push(self, x):
        if self.top == 4:
            print("Stack Overflow")
            return
        self.top += 1
        self.arr[self.top] = x

    # Method to pop element
    def pop(self):
        if self.top == -1:
            print("Stack Underflow")
            return
        self.top -= 1

    # Method to display stack
    def display(self):
        for i in range(self.top, -1, -1):
            print(self.arr[i], end=" ")
        print()

# driver code
if __name__ == "__main__":

    # Creating stack object
    s = Stack()

    # Performing operations
    s.push(10)
    s.push(20)
    s.push(30)

    print("Stack elements: ", end="")
    s.display()

    s.pop()

    print("After pop: ", end="")
    s.display()


            C#

    using System;

// Class representing a Stack
class Stack {
    public int[] arr = new int[5];
    public int top = -1;

    // Method to push element
    public void push(int x) {
        if(top == 4) {
            Console.WriteLine("Stack Overflow");
            return;
        }
        arr[++top] = x;
    }

    // Method to pop element
    public void pop() {
        if(top == -1) {
            Console.WriteLine("Stack Underflow");
            return;
        }
        top--;
    }

    // Method to display stack
    public void display() {
        for(int i = top; i >= 0; i--) {
            Console.Write(arr[i] + " ");
        }
        Console.WriteLine();
    }
}

class main {

    // driver code
    static void Main() {

        // Creating stack object
        Stack s = new Stack();

        // Performing operations
        s.push(10);
        s.push(20);
        s.push(30);

        Console.Write("Stack elements: ");
        s.display();

        s.pop();

        Console.Write("After pop: ");
        s.display();
    }
}


